public class ClassicGrid:DataGridView{
 public ClassicGrid(){DoubleBuffered=true;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);int y=ColumnHeadersHeight+1;foreach(DataGridViewRow r in Rows)if(r.Visible){Rectangle rect=GetRowDisplayRectangle(r.Index,false);if(rect.Height>0)y=Math.Max(y,rect.Bottom);}int bottom=ClientSize.Height-(HorizontalScrollBar.Visible?HorizontalScrollBar.Height:0);using(var pen=new Pen(GridColor)){for(int line=y;line<bottom;line+=RowTemplate.Height)e.Graphics.DrawLine(pen,0,line,ClientSize.Width,line);foreach(DataGridViewColumn c in Columns){Rectangle r=GetColumnDisplayRectangle(c.Index,false);if(r.Width>0)e.Graphics.DrawLine(pen,r.Right-1,y,r.Right-1,bottom);}}}
}
