 ToolStripMenuItem Item(string label,Action action,Keys keys){var item=new ToolStripMenuItem(label){ForeColor=ForeColor,ShortcutKeys=keys};item.Click+=delegate{Safe(action);};return item;}
 ToolStripButton ActionButton(string label,int glyph,Action action){var b=new ToolStripButton(label){Image=Glyph(glyph),TextImageRelation=TextImageRelation.ImageAboveText,AutoSize=false,Size=new Size(77,65),Margin=new Padding(0),ToolTipText=label};b.Click+=delegate{Safe(action);};strip.Items.Add(b);return b;}
 static Bitmap Glyph(int id){var b=new Bitmap(32,32);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;Color[] colors={Color.FromArgb(126,183,171),Color.Silver,Color.Silver,Color.Silver,Color.Silver,Color.FromArgb(174,143,189),Color.FromArgb(150,139,195),Color.FromArgb(127,170,198),Color.FromArgb(174,143,189),Color.FromArgb(192,177,126),Color.LightSteelBlue};using(var p=new Pen(colors[id],2)){if(id==10){g.DrawArc(p,3,3,25,25,205,145);g.DrawArc(p,3,3,25,25,25,145);g.DrawLines(p,new[]{new Point(21,3),new Point(28,6),new Point(25,13)});g.DrawLines(p,new[]{new Point(10,29),new Point(3,26),new Point(6,19)});}else if(id==0){g.DrawLine(p,16,3,16,29);g.DrawLine(p,3,16,29,16);}else if(id==1||id==2){g.DrawEllipse(p,2,2,28,28);if(id==1){g.DrawLine(p,16,7,16,24);g.DrawLines(p,new[]{new Point(9,17),new Point(16,24),new Point(23,17)});}else g.DrawRectangle(p,11,11,10,10);}else if(id==4){g.DrawRectangle(p,8,8,17,22);g.DrawLine(p,5,6,28,6);g.DrawLine(p,12,2,21,2);g.DrawLine(p,13,12,13,25);g.DrawLine(p,20,12,20,25);}else if(id==5){g.DrawRectangle(p,4,3,24,27);g.DrawLines(p,new[]{new Point(8,23),new Point(13,16),new Point(18,20),new Point(25,9)});}else if(id==6){g.DrawEllipse(p,4,4,24,24);g.DrawEllipse(p,11,11,10,10);for(int i=0;i<8;i++){double a=i*Math.PI/4;g.DrawLine(p,(float)(16+12*Math.Cos(a)),(float)(16+12*Math.Sin(a)),(float)(16+16*Math.Cos(a)),(float)(16+16*Math.Sin(a)));}}else if(id==9){g.DrawLines(p,new[]{new Point(2,27),new Point(2,7),new Point(13,7),new Point(16,11),new Point(30,11),new Point(27,27),new Point(2,27)});}else{g.DrawRectangle(p,4,3,18,24);g.DrawRectangle(p,9,8,18,23);if(id==7)g.DrawLines(p,new[]{new Point(13,20),new Point(18,26),new Point(24,18)});else{g.DrawLine(p,14,15,14,25);g.DrawLine(p,21,15,21,25);}}}}return b;}
 void Safe(Action action){try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Nocturnal",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 IEnumerable<Job> Selected(){return grid.SelectedRows.Cast<DataGridViewRow>().Select(x=>x.Tag as Job).Where(x=>x!=null).ToArray();}
 void UpdateActions(){var selection=Selected().ToList();startButton.Enabled=selection.Any(x=>!x.Running&&x.Status!="Concluído");pauseButton.Enabled=selection.Any(x=>x.Running||x.Status=="Na fila");removeButton.Enabled=selection.Count>0&&selection.All(x=>!x.Running);detailsButton.Enabled=selection.Count==1;}
 void SelectFilter(string name){foreach(TreeNode n in tree.Nodes){if(n.Text==name){tree.SelectedNode=n;return;}}}
 bool Matches(Job j){if(filter=="Todos os downloads")return true;if(filter=="Completos")return j.Status=="Concluído";if(filter=="Incompletos")return j.Status!="Concluído";return CategoryFolders.Category(j.Path,j.Video,j.AudioOnly)==filter;}
 void AddRow(Job j){int n=grid.Rows.Add();var r=grid.Rows[n];r.Tag=j;rows[j]=r;}
 void RefreshRows(){double seconds=Math.Max(.1,watch.Elapsed.TotalSeconds);watch.Restart();double total=0;if(grid.CurrentCell!=null&&!Matches((Job)grid.CurrentCell.OwningRow.Tag))grid.CurrentCell=null;foreach(Job j in jobs){long old;sampled.TryGetValue(j,out old);double rate=j.Running&&!j.Video?Math.Max(0,j.Done-old)/seconds:0;sampled[j]=j.Done;rates[j]=rate;total+=rate;DataGridViewRow row=rows[j];string progress=j.Size>0?(Math.Min(100,100.0*j.Done/j.Size).ToString("0.00")+" %"):TransferWindow.Bytes(j.Done);if(j.Video){var match=System.Text.RegularExpressions.Regex.Match(j.Status,@"\d+(?:\.\d+)?%");progress=match.Success?match.Value:"—";}if(j.Status=="Concluído")progress="Completo";string eta=rate>0&&j.Size>j.Done?TimeSpan.FromSeconds(Math.Min(315360000,(j.Size-j.Done)/rate)).ToString(@"hh\:mm\:ss"):"—";object[] values={j.Name,j.Size>0?TransferWindow.Bytes(j.Size):"—",progress,eta,rate>0?TransferWindow.Bytes(rate)+"/s":"—",j.Status.StartsWith("[download]")?"Baixando mídia":j.Status,CategoryFolders.Category(j.Path,j.Video,j.AudioOnly)};for(int i=0;i<values.Length;i++)if(!Equals(row.Cells[i].Value,values[i]))row.Cells[i].Value=values[i];row.Cells[5].ToolTipText=j.Error;row.Visible=Matches(j);}
  status.Text=jobs.Count+" downloads   |   "+jobs.Count(j=>j.Running)+" ativos   |   "+TransferWindow.Bytes(total)+"/s (arquivos)   |   "+(stopped?"Fila parada":"Fila ativa")+"   |   "+root;UpdateActions();}
 void StartSelected(){foreach(Job j in Selected())if(!j.Running&&j.Status!="Concluído"){j.Status="Na fila";j.Error="";}stopped=false;Save();Schedule();RefreshRows();}
 void Pause(Job j){if(j.Running){j.Status="Pausando";j.Cancel.Cancel();}else if(j.Status=="Na fila")j.Status="Pausado";}
 void PauseSelected(){foreach(Job j in Selected())Pause(j);Save();RefreshRows();}
 void StartQueue(){stopped=false;foreach(Job j in jobs)if(!j.Running&&j.Status=="Pausado")j.Status="Na fila";Save();Schedule();RefreshRows();}
 void StopQueue(){stopped=true;foreach(Job j in jobs)Pause(j);Save();RefreshRows();}
 void RemoveSelected(){var selection=Selected().ToList();if(selection.Any(j=>j.Running))throw new Exception("Pause e aguarde antes de excluir da lista.");foreach(Job j in selection){TransferWindow window;if(progressWindows.TryGetValue(j,out window))window.Close();grid.Rows.Remove(rows[j]);rows.Remove(j);jobs.Remove(j);sampled.Remove(j);rates.Remove(j);}Save();RefreshRows();}
 void Details(){Job j=Selected().FirstOrDefault();if(j!=null)ShowProgress(j);}
 void ShowProgress(Job j){TransferWindow existing;if(progressWindows.TryGetValue(j,out existing)&&!existing.IsDisposed){if(existing.WindowState==FormWindowState.Minimized)existing.WindowState=FormWindowState.Normal;existing.Activate();return;}var window=new TransferWindow(j,delegate{if(j.Running)Pause(j);else if(j.Status!="Concluído"){j.Status="Na fila";j.Error="";stopped=false;}Save();Schedule();},Save);progressWindows[j]=window;window.FormClosed+=delegate{progressWindows.Remove(j);};window.Show(this);}
 void Options(){using(var d=new QueueOptions(maximum,stopped))if(d.ShowDialog(this)==DialogResult.OK){maximum=d.Maximum;stopped=d.Stopped;QueueOptions.Store(maximum);if(stopped)foreach(Job j in jobs)Pause(j);Save();Schedule();RefreshRows();}}
 void ChooseRoot(){using(var d=new FolderBrowserDialog{SelectedPath=root,Description="Pasta base; novos downloads serão organizados em subpastas por tipo."})if(d.ShowDialog(this)==DialogResult.OK){root=d.SelectedPath;CategoryFolders.SaveRoot(root);RefreshRows();}}
 void OpenConverter(){if(converterWindow!=null&&!converterWindow.IsDisposed){converterWindow.Activate();return;}Job selected=Selected().FirstOrDefault();string path=selected!=null&&selected.Status=="Concluído"&&File.Exists(selected.Path)?selected.Path:null;converterWindow=new ConverterWindow(path);converterWindow.Show(this);}
 void OpenRoot(){Directory.CreateDirectory(root);Process.Start("explorer.exe",Engine.Quote(root));}
 void OpenSelected(){Job j=Selected().FirstOrDefault();string folder=j==null?root:Path.GetDirectoryName(j.Path);Directory.CreateDirectory(folder);Process.Start("explorer.exe",Engine.Quote(folder));}
 void AddDialog(string url){if(adding||closing)return;adding=true;try{using(var d=new AddTransferDialog(url,root)){if(d.ShowDialog(this)!=DialogResult.OK)return;Job job=d.Result;if(jobs.Any(x=>string.Equals(x.Path,job.Path,StringComparison.OrdinalIgnoreCase)))throw new Exception("Este destino já está na fila.");jobs.Add(job);AddRow(job);grid.ClearSelection();rows[job].Selected=true;Save();Schedule();RefreshRows();ShowProgress(job);}}finally{adding=false;}}
 void ReadIncoming(){if(adding||closing)return;string dir=Path.Combine(Path.GetDirectoryName(state),"incoming");if(!Directory.Exists(dir))return;string path=Directory.GetFiles(dir,"*.txt").FirstOrDefault();if(path==null)return;try{string url=File.ReadAllText(path);Engine.Validate(url);File.Delete(path);if(WindowState==FormWindowState.Minimized)WindowState=FormWindowState.Normal;Activate();Safe(()=>AddDialog(url));}catch(Exception ex){status.Text="Falha ao receber link: "+ex.Message;}}
 void Schedule(){if(closing||preview||stopped)return;int available=maximum-jobs.Count(j=>j.Running);foreach(Job j in jobs.Where(j=>!j.Running&&j.Status=="Na fila").Take(Math.Max(0,available)).ToList()){Task task=Run(j);transfers.Add(task);}transfers.RemoveAll(t=>t.IsCompleted);}
 async Task Run(Job j){j.Running=true;j.Cancel=new CancellationTokenSource();j.Status="Conectando";if(!preview&&!closing)ShowProgress(j);try{if(j.Video)await Engine.Video(j,j.Cancel.Token);else{j.Status="Baixando";await Engine.Download(j,j.Cancel.Token);}j.Status="Concluído";j.Error="";}catch(OperationCanceledException){j.Status="Pausado";}catch(Exception ex){j.Status=j.Cancel.IsCancellationRequested?"Pausado":"Erro";j.Error=DownloadErrors.Describe(ex,j.Video);if(!closing&&!IsDisposed)BeginInvoke((Action)(()=>{if(!IsDisposed)ShowProgress(j);}));}finally{j.Running=false;j.Cancel.Dispose();if(!IsDisposed){Save();RefreshRows();}}}
 void LoadQueue(){if(!File.Exists(state))return;try{var loaded=new JavaScriptSerializer().Deserialize<List<Job>>(File.ReadAllText(state));if(loaded!=null)foreach(Job j in loaded){if(string.IsNullOrEmpty(j.Path)||string.IsNullOrEmpty(j.Url))continue;j.Running=false;if(j.Status!="Concluído")j.Status="Pausado";jobs.Add(j);AddRow(j);}}catch(Exception ex){MessageBox.Show(this,"Não foi possível ler a fila. Ela não será sobrescrita nesta sessão.\n"+ex.Message,"Fila preservada");preview=true;}}
 void Save(){if(preview)return;try{Directory.CreateDirectory(Path.GetDirectoryName(state));string temp=state+".tmp";File.WriteAllText(temp,new JavaScriptSerializer().Serialize(jobs));if(File.Exists(state))File.Replace(temp,state,null);else File.Move(temp,state);}catch(Exception ex){status.Text="Não foi possível salvar a fila: "+ex.Message;}}
 async void HandleClosing(object sender,FormClosingEventArgs e){if(allowClose)return;e.Cancel=true;if(closing)return;closing=true;await Task.Yield();timer.Stop();foreach(Job j in jobs)Pause(j);Enabled=false;try{if(converterWindow!=null&&!converterWindow.IsDisposed)await converterWindow.CloseSafely();await Task.WhenAll(transfers.ToArray());Save();}finally{if(!IsDisposed){allowClose=true;Close();}}}
 public void PreviewData(){foreach(var j in new[]{new Job{Name="documento.pdf",Path="documento.pdf",Url="https://example.test/documento.pdf",Status="Concluído",Size=6281450,Done=6281450},new Job{Name="video.mp4",Path="video.mp4",Url="https://example.test/video.mp4",Size=12800000000,Done=1390000000,Status="Pausado",Video=true},new Job{Name="musica.mp3",Path="musica.mp3",Url="https://example.test/music",AudioOnly=true,Video=true,Status="Na fila"}}){jobs.Add(j);AddRow(j);}RefreshRows();}
}

