 void AcceptDownload(){string link=url.Text.Trim();Engine.Validate(link);bool audio=mode.SelectedIndex==2,video=mode.SelectedIndex!=0;string filename=video?(audio?"Áudio ":"Vídeo ")+DateTime.Now.ToString("yyyyMMdd-HHmmss")+(audio?".mp3":".mp4"):Uri.UnescapeDataString(Path.GetFileName(new Uri(link).AbsolutePath));foreach(char c in Path.GetInvalidFileNameChars())filename=filename.Replace(c,'_');if(string.IsNullOrWhiteSpace(filename))filename="arquivo.bin";string folder=CategoryFolders.Destination(root,filename,video,audio);Directory.CreateDirectory(folder);using(var save=new SaveFileDialog{Title="Salvar em "+CategoryFolders.Category(filename,video,audio),InitialDirectory=folder,FileName=filename,Filter=audio?"Áudio MP3|*.mp3":video?"Vídeo MP4|*.mp4":"Todos os arquivos|*.*",DefaultExt=audio?"mp3":video?"mp4":"",OverwritePrompt=true}){if(save.ShowDialog(this)!=DialogResult.OK)return;string path=video?Path.ChangeExtension(save.FileName,audio?"mp3":"mp4"):save.FileName;if(File.Exists(path))throw new Exception("Escolha um nome novo; arquivos existentes serão preservados.");Result=new Job{Url=link,Path=path,Name=Path.GetFileName(path),Video=video,AudioOnly=audio,AudioKbps=audio?new[]{320,256,192,128}[quality.SelectedIndex]:320,MaxHeight=video&&!audio?new[]{0,2160,1440,1080,720,480,360}[quality.SelectedIndex]:0};DialogResult=DialogResult.OK;Close();}}
